BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Pacemakers & ICDs' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Pacemakers & ICDs', 'Device indications, troubleshooting, and chest pain priorities', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - Pacemakers and ICDs (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'Pacemakers and ICDs - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Pacemaker definition" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Pacemaker definition" is most accurate?', '[{"id": "a", "text": "Pacemakers only deliver defibrillation shocks in this note."}, {"id": "b", "text": "A pacemaker is an implanted device that delivers electrical impulses to maintain adequate heart rate and contraction."}, {"id": "c", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "d", "text": "Pacemakers are used to raise blood volume directly in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because A pacemaker is an implanted device that delivers electrical impulses to maintain adequate heart rate and contraction. Assess rhythm response and perfusion after pacing initiation.', 'Pacemakers and ICDs - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Temporary vs permanent pacing" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Temporary vs permanent pacing" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "b", "text": "Match pacing type to acute versus chronic rhythm support needs."}, {"id": "c", "text": "Permanent pacemakers are external bedside-only in this note."}, {"id": "d", "text": "Temporary pacing is lifelong default therapy in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Temporary pacing uses external wires (e.g., acute bradycardia/post-MI), while permanent pacing is surgically implanted under skin. Match pacing type to acute versus chronic rhythm support needs.', 'Pacemakers and ICDs - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Bradycardia indication" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Bradycardia indication" in Pacemakers & ICDs?', '[{"id": "a", "text": "Asymptomatic tachycardia is primary pacing indication in this note."}, {"id": "b", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "c", "text": "Bradycardia is never paced in this note."}, {"id": "d", "text": "Pacemaker indication includes symptomatic bradycardia with heart rate below 60 bpm."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pacemaker indication includes symptomatic bradycardia with heart rate below 60 bpm. Treat symptomatic low-rate states to prevent syncope and hypoperfusion.', 'Pacemakers and ICDs - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Heart block indication" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Heart block indication" in Pacemakers & ICDs?', '[{"id": "a", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "b", "text": "AV block is contraindication to pacing in this note."}, {"id": "c", "text": "High-grade AV block should trigger prompt pacing preparedness."}, {"id": "d", "text": "Failure to capture means no spike present in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pacemaker indications include second-degree type II and third-degree AV block. High-grade AV block should trigger prompt pacing preparedness.', 'Pacemakers and ICDs - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Other pacing indications" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Other pacing indications" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Other listed pacing indications include asystole with reversible cause, sick sinus syndrome, and post-cardiac surgery prophylaxis."}, {"id": "b", "text": "Only ventricular tachycardia is paced in this note."}, {"id": "c", "text": "Pacemaker use is excluded after cardiac surgery in this note."}, {"id": "d", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}]'::jsonb, '["a"]'::jsonb, 'Correct because Other listed pacing indications include asystole with reversible cause, sick sinus syndrome, and post-cardiac surgery prophylaxis. Recognize broader pacing use beyond simple bradycardia.', 'Pacemakers and ICDs - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "ECG post-implant monitoring" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "ECG post-implant monitoring" is most accurate?', '[{"id": "a", "text": "ECG is unnecessary after implant in this note."}, {"id": "b", "text": "Correlate spikes with electrical/mechanical outcomes continuously."}, {"id": "c", "text": "Spikes indicate malfunction by default in this note."}, {"id": "d", "text": "All magnetic exposures are harmless in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Nursing care includes ECG monitoring to verify pacing spikes and appropriate response. Correlate spikes with electrical/mechanical outcomes continuously.', 'Pacemakers and ICDs - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Pacing threshold" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Pacing threshold" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "b", "text": "Pacing threshold is the lowest current needed to pace the heart."}, {"id": "c", "text": "Threshold has no relation to pacing effectiveness in this note."}, {"id": "d", "text": "Device identification is unnecessary in emergencies in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Pacing threshold is the lowest current needed to pace the heart. Optimize threshold to ensure reliable capture with minimal energy.', 'Pacemakers and ICDs - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Failure to pace" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Failure to pace" in Pacemakers & ICDs?', '[{"id": "a", "text": "Failure to pace is normal after implantation in this note."}, {"id": "b", "text": "Failure to pace shows spike with no QRS in this note."}, {"id": "c", "text": "Recognize no-spike failure quickly to prevent brady-asystolic events."}, {"id": "d", "text": "Magnetic field precautions are optional and have no device implications."}]'::jsonb, '["c"]'::jsonb, 'Correct because Failure to pace is identified by absence of pacing spike when one is expected. Recognize no-spike failure quickly to prevent brady-asystolic events.', 'Pacemakers and ICDs - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Failure to capture" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Failure to capture" in Pacemakers & ICDs?', '[{"id": "a", "text": "Spike followed by QRS always indicates failure in this note."}, {"id": "b", "text": "Failure to capture is pacing spike without resulting QRS complex."}, {"id": "c", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "d", "text": "Exercise immediately after shock is advised in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Failure to capture is pacing spike without resulting QRS complex. Spike-no-QRS pattern requires urgent evaluation of lead/output issues.', 'Pacemakers and ICDs - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Arm movement restriction" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Arm movement restriction" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "b", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "c", "text": "Protect lead position in early post-op period."}, {"id": "d", "text": "Aggressive overhead arm exercise is encouraged immediately in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because After implant, restrict affected arm movement for 24–48 hours to prevent lead displacement. Protect lead position in early post-op period.', 'Pacemakers and ICDs - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Electromagnetic precautions" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Electromagnetic precautions" is most accurate?', '[{"id": "a", "text": "Patients should avoid strong electromagnetic fields (e.g., MRI, arc welding, certain equipment)."}, {"id": "b", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "c", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "d", "text": "Repeated shocks can be ignored if conscious in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because Patients should avoid strong electromagnetic fields (e.g., MRI, arc welding, certain equipment). Prevent device interference through exposure counseling.', 'Pacemakers and ICDs - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Patient ID and symptom reporting" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Patient ID and symptom reporting" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Hiccups are always benign in this context in this note."}, {"id": "b", "text": "Device identification is unnecessary in emergencies in this note."}, {"id": "c", "text": "Medications are given before ABC assessment in this note."}, {"id": "d", "text": "Early symptom reporting can identify displacement or pacing failure."}]'::jsonb, '["d"]'::jsonb, 'Correct because Patients should carry pacemaker ID card and report hiccups, dizziness, or syncope. Early symptom reporting can identify displacement or pacing failure.', 'Pacemakers and ICDs - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "ICD function" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "ICD function" in Pacemakers & ICDs?', '[{"id": "a", "text": "ICD continuously monitors rhythm and delivers shock for ventricular fibrillation or ventricular tachycardia."}, {"id": "b", "text": "ICD does not treat ventricular arrhythmias in this note."}, {"id": "c", "text": "No labs are needed for chest pain in this note."}, {"id": "d", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}]'::jsonb, '["a"]'::jsonb, 'Correct because ICD continuously monitors rhythm and delivers shock for ventricular fibrillation or ventricular tachycardia. Use ICD in patients at risk for sudden cardiac death from lethal ventricular rhythms.', 'Pacemakers and ICDs - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "If ICD fires" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "If ICD fires" in Pacemakers & ICDs?', '[{"id": "a", "text": "ICD firing never requires follow-up in this note."}, {"id": "b", "text": "Post-shock self-management reduces injury and ensures urgent follow-up."}, {"id": "c", "text": "Exercise immediately after shock is advised in this note."}, {"id": "d", "text": "NTG is safe regardless of BP in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because If ICD fires, patient should lie down, note time, and notify provider if symptoms continue. Post-shock self-management reduces injury and ensures urgent follow-up.', 'Pacemakers and ICDs - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Bystander sensation with ICD" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Bystander sensation with ICD" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "b", "text": "Flat Trendelenburg is best for HF/SOB in this note."}, {"id": "c", "text": "People touching the patient during ICD discharge may feel mild shock that is not dangerous."}, {"id": "d", "text": "No one near patient feels anything in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because People touching the patient during ICD discharge may feel mild shock that is not dangerous. Provide reassurance to family and staff to reduce panic during discharge events.', 'Pacemakers and ICDs - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "ICD storm emergency" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "ICD storm emergency" is most accurate?', '[{"id": "a", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "b", "text": "ICD storm is routine expected function in this note."}, {"id": "c", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "d", "text": "Escalate recurrent shocks urgently for rhythm stabilization."}]'::jsonb, '["d"]'::jsonb, 'Correct because Repeated ICD firing should be reported immediately as an emergency (ICD storm). Escalate recurrent shocks urgently for rhythm stabilization.', 'Pacemakers and ICDs - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Chest pain initial priorities" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Chest pain initial priorities" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Chest pain protocol starts with ABC assessment, oxygen if saturation <90%, vitals, and 12-lead ECG within 10 minutes."}, {"id": "b", "text": "Medications are given before ABC assessment in this note."}, {"id": "c", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "d", "text": "Magnetic field precautions are optional and have no device implications."}]'::jsonb, '["a"]'::jsonb, 'Correct because Chest pain protocol starts with ABC assessment, oxygen if saturation <90%, vitals, and 12-lead ECG within 10 minutes. Rapid physiologic stabilization and STEMI detection are first-line priorities.', 'Pacemakers and ICDs - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Chest pain workflow continuation" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Chest pain workflow continuation" in Pacemakers & ICDs?', '[{"id": "a", "text": "No labs are needed for chest pain in this note."}, {"id": "b", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "c", "text": "Establish access and objective diagnostics while initiating evidence-based medication sequence."}, {"id": "d", "text": "Heparin is given before aspirin in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Protocol includes large-bore IV access, labs (troponin, CK-MB, BMP), and meds sequence: aspirin, nitroglycerin, morphine if needed, then heparin. Establish access and objective diagnostics while initiating evidence-based medication sequence.', 'Pacemakers and ICDs - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Nitroglycerin safety" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Nitroglycerin safety" in Pacemakers & ICDs?', '[{"id": "a", "text": "Check blood pressure before nitroglycerin; avoid nitroglycerin if systolic BP <90 or recent sildenafil use within 24–48 hours."}, {"id": "b", "text": "Sildenafil timing has no relevance in this note."}, {"id": "c", "text": "NTG is safe regardless of BP in this note."}, {"id": "d", "text": "Magnetic field precautions are optional and have no device implications."}]'::jsonb, '["a"]'::jsonb, 'Correct because Check blood pressure before nitroglycerin; avoid nitroglycerin if systolic BP <90 or recent sildenafil use within 24–48 hours. Prevent severe hypotension from contraindicated nitrate administration.', 'Pacemakers and ICDs - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Positioning HF/SOB" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Positioning HF/SOB" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Use positioning to improve oxygenation while other therapies are prepared."}, {"id": "b", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "c", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "d", "text": "Flat Trendelenburg is best for HF/SOB in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because For heart failure/SOB, best position is HOB elevated 30–45° (Fowler) to reduce preload and ease breathing. Use positioning to improve oxygenation while other therapies are prepared.', 'Pacemakers and ICDs - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Positioning hypotension/shock" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Positioning hypotension/shock" is most accurate?', '[{"id": "a", "text": "Trendelenburg is preferred for all hypotension in this note."}, {"id": "b", "text": "Leg lowering improves hypotension in this note."}, {"id": "c", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "d", "text": "For hypotension/shock, position supine with legs elevated 15–30° to increase venous return."}]'::jsonb, '["d"]'::jsonb, 'Correct because For hypotension/shock, position supine with legs elevated 15–30° to increase venous return. Use immediate non-pharmacologic perfusion support while treating cause.', 'Pacemakers and ICDs - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Cardiogenic shock position caution" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Cardiogenic shock position caution" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Pacemakers only deliver defibrillation shocks in this note."}, {"id": "b", "text": "Balance BP support with cardiopulmonary tolerance in cardiogenic states."}, {"id": "c", "text": "Cardiogenic shock requires sitting upright always in this note."}, {"id": "d", "text": "Trendelenburg is first-line for cardiogenic shock in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because For cardiogenic shock, note recommends supine with caution and to avoid Trendelenburg. Balance BP support with cardiopulmonary tolerance in cardiogenic states.', 'Pacemakers and ICDs - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Pericarditis and post-op positioning" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Pericarditis and post-op positioning" in Pacemakers & ICDs?', '[{"id": "a", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "b", "text": "Pericarditis is best managed flat supine in this note."}, {"id": "c", "text": "Pericarditis position is sit up/lean forward; post-cardiac surgery preferred is semi-Fowler for comfort and lung expansion."}, {"id": "d", "text": "Permanent pacemakers are external bedside-only in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pericarditis position is sit up/lean forward; post-cardiac surgery preferred is semi-Fowler for comfort and lung expansion. Condition-specific positioning can reduce pain and improve ventilation.', 'Pacemakers and ICDs - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Lifestyle diet teaching" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Lifestyle diet teaching" in Pacemakers & ICDs?', '[{"id": "a", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "b", "text": "Asymptomatic tachycardia is primary pacing indication in this note."}, {"id": "c", "text": "Long-term dietary adherence reduces cardiovascular decompensation risk."}, {"id": "d", "text": "High-sodium canned foods are recommended in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Diet teaching includes sodium restriction <2 g/day, low saturated fat/cholesterol, high fiber/fruits/vegetables, and avoiding processed high-salt foods. Long-term dietary adherence reduces cardiovascular decompensation risk.', 'Pacemakers and ICDs - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Lifestyle fluid/weight teaching" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Lifestyle fluid/weight teaching" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Lifestyle instructions include no smoking, weight loss if BMI >25, fluid restriction 1.5–2 L/day in HF, and daily weight reporting if gain >2 lb."}, {"id": "b", "text": "Daily weight changes are irrelevant in this note."}, {"id": "c", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "d", "text": "First-degree block is the only mandatory pacing indication in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because Lifestyle instructions include no smoking, weight loss if BMI >25, fluid restriction 1.5–2 L/day in HF, and daily weight reporting if gain >2 lb. Self-monitoring and fluid control detect and prevent worsening heart failure.', 'Pacemakers and ICDs - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "NCLEX perfusion tip" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "NCLEX perfusion tip" is most accurate?', '[{"id": "a", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "b", "text": "Documentation precedes circulation in this note."}, {"id": "c", "text": "Stabilize airway-breathing-circulation before noncritical steps."}, {"id": "d", "text": "Only ventricular tachycardia is paced in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because NCLEX tip emphasizes avoiding Trendelenburg for hypotension and prioritizing oxygenation/circulation first. Stabilize airway-breathing-circulation before noncritical steps.', 'Pacemakers and ICDs - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Pacemaker definition" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Pacemaker definition" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "b", "text": "Pacemakers only deliver defibrillation shocks in this note."}, {"id": "c", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "d", "text": "A pacemaker is an implanted device that delivers electrical impulses to maintain adequate heart rate and contraction."}]'::jsonb, '["d"]'::jsonb, 'Correct because A pacemaker is an implanted device that delivers electrical impulses to maintain adequate heart rate and contraction. Assess rhythm response and perfusion after pacing initiation.', 'Pacemakers and ICDs - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Temporary vs permanent pacing" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Temporary vs permanent pacing" in Pacemakers & ICDs?', '[{"id": "a", "text": "Permanent pacemakers are external bedside-only in this note."}, {"id": "b", "text": "Temporary pacing is lifelong default therapy in this note."}, {"id": "c", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "d", "text": "Match pacing type to acute versus chronic rhythm support needs."}]'::jsonb, '["d"]'::jsonb, 'Correct because Temporary pacing uses external wires (e.g., acute bradycardia/post-MI), while permanent pacing is surgically implanted under skin. Match pacing type to acute versus chronic rhythm support needs.', 'Pacemakers and ICDs - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Bradycardia indication" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Bradycardia indication" in Pacemakers & ICDs?', '[{"id": "a", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "b", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "c", "text": "Pacemaker indication includes symptomatic bradycardia with heart rate below 60 bpm."}, {"id": "d", "text": "Bradycardia is never paced in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pacemaker indication includes symptomatic bradycardia with heart rate below 60 bpm. Treat symptomatic low-rate states to prevent syncope and hypoperfusion.', 'Pacemakers and ICDs - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Heart block indication" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Heart block indication" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Spike followed by QRS always indicates failure in this note."}, {"id": "b", "text": "AV block is contraindication to pacing in this note."}, {"id": "c", "text": "High-grade AV block should trigger prompt pacing preparedness."}, {"id": "d", "text": "Magnetic field precautions are optional and have no device implications."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pacemaker indications include second-degree type II and third-degree AV block. High-grade AV block should trigger prompt pacing preparedness.', 'Pacemakers and ICDs - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Other pacing indications" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Other pacing indications" is most accurate?', '[{"id": "a", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "b", "text": "Other listed pacing indications include asystole with reversible cause, sick sinus syndrome, and post-cardiac surgery prophylaxis."}, {"id": "c", "text": "Pacemaker use is excluded after cardiac surgery in this note."}, {"id": "d", "text": "Arm restriction is unnecessary after implant in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Other listed pacing indications include asystole with reversible cause, sick sinus syndrome, and post-cardiac surgery prophylaxis. Recognize broader pacing use beyond simple bradycardia.', 'Pacemakers and ICDs - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "ECG post-implant monitoring" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "ECG post-implant monitoring" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Arc welding is recommended with pacemakers in this note."}, {"id": "b", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "c", "text": "Correlate spikes with electrical/mechanical outcomes continuously."}, {"id": "d", "text": "Spikes indicate malfunction by default in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Nursing care includes ECG monitoring to verify pacing spikes and appropriate response. Correlate spikes with electrical/mechanical outcomes continuously.', 'Pacemakers and ICDs - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Pacing threshold" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Pacing threshold" in Pacemakers & ICDs?', '[{"id": "a", "text": "Hiccups are always benign in this context in this note."}, {"id": "b", "text": "Threshold is the maximum tolerated blood pressure in this note."}, {"id": "c", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "d", "text": "Pacing threshold is the lowest current needed to pace the heart."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pacing threshold is the lowest current needed to pace the heart. Optimize threshold to ensure reliable capture with minimal energy.', 'Pacemakers and ICDs - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Failure to pace" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Failure to pace" in Pacemakers & ICDs?', '[{"id": "a", "text": "Recognize no-spike failure quickly to prevent brady-asystolic events."}, {"id": "b", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "c", "text": "Failure to pace is normal after implantation in this note."}, {"id": "d", "text": "ICD does not treat ventricular arrhythmias in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because Failure to pace is identified by absence of pacing spike when one is expected. Recognize no-spike failure quickly to prevent brady-asystolic events.', 'Pacemakers and ICDs - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Failure to capture" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Failure to capture" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "ICD firing never requires follow-up in this note."}, {"id": "b", "text": "Failure to capture means no spike present in this note."}, {"id": "c", "text": "Failure to capture is pacing spike without resulting QRS complex."}, {"id": "d", "text": "Spike followed by QRS always indicates failure in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Failure to capture is pacing spike without resulting QRS complex. Spike-no-QRS pattern requires urgent evaluation of lead/output issues.', 'Pacemakers and ICDs - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Arm movement restriction" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Arm movement restriction" is most accurate?', '[{"id": "a", "text": "Protect lead position in early post-op period."}, {"id": "b", "text": "Arm restriction is unnecessary after implant in this note."}, {"id": "c", "text": "Aggressive overhead arm exercise is encouraged immediately in this note."}, {"id": "d", "text": "No one near patient feels anything in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because After implant, restrict affected arm movement for 24–48 hours to prevent lead displacement. Protect lead position in early post-op period.', 'Pacemakers and ICDs - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Electromagnetic precautions" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Electromagnetic precautions" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "All magnetic exposures are harmless in this note."}, {"id": "b", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "c", "text": "Arc welding is recommended with pacemakers in this note."}, {"id": "d", "text": "Patients should avoid strong electromagnetic fields (e.g., MRI, arc welding, certain equipment)."}]'::jsonb, '["d"]'::jsonb, 'Correct because Patients should avoid strong electromagnetic fields (e.g., MRI, arc welding, certain equipment). Prevent device interference through exposure counseling.', 'Pacemakers and ICDs - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Patient ID and symptom reporting" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Patient ID and symptom reporting" in Pacemakers & ICDs?', '[{"id": "a", "text": "12-lead ECG can be delayed several hours in this note."}, {"id": "b", "text": "Hiccups are always benign in this context in this note."}, {"id": "c", "text": "Device identification is unnecessary in emergencies in this note."}, {"id": "d", "text": "Early symptom reporting can identify displacement or pacing failure."}]'::jsonb, '["d"]'::jsonb, 'Correct because Patients should carry pacemaker ID card and report hiccups, dizziness, or syncope. Early symptom reporting can identify displacement or pacing failure.', 'Pacemakers and ICDs - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "ICD function" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "ICD function" in Pacemakers & ICDs?', '[{"id": "a", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "b", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "c", "text": "ICD is for sinus bradycardia only in this note."}, {"id": "d", "text": "ICD continuously monitors rhythm and delivers shock for ventricular fibrillation or ventricular tachycardia."}]'::jsonb, '["d"]'::jsonb, 'Correct because ICD continuously monitors rhythm and delivers shock for ventricular fibrillation or ventricular tachycardia. Use ICD in patients at risk for sudden cardiac death from lethal ventricular rhythms.', 'Pacemakers and ICDs - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "If ICD fires" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "If ICD fires" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Sildenafil timing has no relevance in this note."}, {"id": "b", "text": "Exercise immediately after shock is advised in this note."}, {"id": "c", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "d", "text": "Post-shock self-management reduces injury and ensures urgent follow-up."}]'::jsonb, '["d"]'::jsonb, 'Correct because If ICD fires, patient should lie down, note time, and notify provider if symptoms continue. Post-shock self-management reduces injury and ensures urgent follow-up.', 'Pacemakers and ICDs - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Bystander sensation with ICD" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Bystander sensation with ICD" is most accurate?', '[{"id": "a", "text": "People touching the patient during ICD discharge may feel mild shock that is not dangerous."}, {"id": "b", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "c", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "d", "text": "Position has no respiratory impact in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because People touching the patient during ICD discharge may feel mild shock that is not dangerous. Provide reassurance to family and staff to reduce panic during discharge events.', 'Pacemakers and ICDs - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "ICD storm emergency" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "ICD storm emergency" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Escalate recurrent shocks urgently for rhythm stabilization."}, {"id": "b", "text": "ICD storm is routine expected function in this note."}, {"id": "c", "text": "Repeated shocks can be ignored if conscious in this note."}, {"id": "d", "text": "Magnetic field precautions are optional and have no device implications."}]'::jsonb, '["a"]'::jsonb, 'Correct because Repeated ICD firing should be reported immediately as an emergency (ICD storm). Escalate recurrent shocks urgently for rhythm stabilization.', 'Pacemakers and ICDs - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Chest pain initial priorities" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Chest pain initial priorities" in Pacemakers & ICDs?', '[{"id": "a", "text": "Chest pain protocol starts with ABC assessment, oxygen if saturation <90%, vitals, and 12-lead ECG within 10 minutes."}, {"id": "b", "text": "Cardiogenic shock requires sitting upright always in this note."}, {"id": "c", "text": "Medications are given before ABC assessment in this note."}, {"id": "d", "text": "12-lead ECG can be delayed several hours in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because Chest pain protocol starts with ABC assessment, oxygen if saturation <90%, vitals, and 12-lead ECG within 10 minutes. Rapid physiologic stabilization and STEMI detection are first-line priorities.', 'Pacemakers and ICDs - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Chest pain workflow continuation" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Chest pain workflow continuation" in Pacemakers & ICDs?', '[{"id": "a", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "b", "text": "Post-op position should always be Trendelenburg in this note."}, {"id": "c", "text": "Heparin is given before aspirin in this note."}, {"id": "d", "text": "Establish access and objective diagnostics while initiating evidence-based medication sequence."}]'::jsonb, '["d"]'::jsonb, 'Correct because Protocol includes large-bore IV access, labs (troponin, CK-MB, BMP), and meds sequence: aspirin, nitroglycerin, morphine if needed, then heparin. Establish access and objective diagnostics while initiating evidence-based medication sequence.', 'Pacemakers and ICDs - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Nitroglycerin safety" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Nitroglycerin safety" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Sildenafil timing has no relevance in this note."}, {"id": "b", "text": "Fiber should be minimized in this note."}, {"id": "c", "text": "Check blood pressure before nitroglycerin; avoid nitroglycerin if systolic BP <90 or recent sildenafil use within 24–48 hours."}, {"id": "d", "text": "NTG is safe regardless of BP in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Check blood pressure before nitroglycerin; avoid nitroglycerin if systolic BP <90 or recent sildenafil use within 24–48 hours. Prevent severe hypotension from contraindicated nitrate administration.', 'Pacemakers and ICDs - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Positioning HF/SOB" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Positioning HF/SOB" is most accurate?', '[{"id": "a", "text": "Flat Trendelenburg is best for HF/SOB in this note."}, {"id": "b", "text": "Position has no respiratory impact in this note."}, {"id": "c", "text": "Daily weight changes are irrelevant in this note."}, {"id": "d", "text": "Use positioning to improve oxygenation while other therapies are prepared."}]'::jsonb, '["d"]'::jsonb, 'Correct because For heart failure/SOB, best position is HOB elevated 30–45° (Fowler) to reduce preload and ease breathing. Use positioning to improve oxygenation while other therapies are prepared.', 'Pacemakers and ICDs - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Positioning hypotension/shock" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Positioning hypotension/shock" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "b", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "c", "text": "For hypotension/shock, position supine with legs elevated 15–30° to increase venous return."}, {"id": "d", "text": "Leg lowering improves hypotension in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because For hypotension/shock, position supine with legs elevated 15–30° to increase venous return. Use immediate non-pharmacologic perfusion support while treating cause.', 'Pacemakers and ICDs - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Cardiogenic shock position caution" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Cardiogenic shock position caution" in Pacemakers & ICDs?', '[{"id": "a", "text": "Cardiogenic shock requires sitting upright always in this note."}, {"id": "b", "text": "Balance BP support with cardiopulmonary tolerance in cardiogenic states."}, {"id": "c", "text": "Pacemakers are used to raise blood volume directly in this note."}, {"id": "d", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}]'::jsonb, '["b"]'::jsonb, 'Correct because For cardiogenic shock, note recommends supine with caution and to avoid Trendelenburg. Balance BP support with cardiopulmonary tolerance in cardiogenic states.', 'Pacemakers and ICDs - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Pericarditis and post-op positioning" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Pericarditis and post-op positioning" in Pacemakers & ICDs?', '[{"id": "a", "text": "Temporary pacing is lifelong default therapy in this note."}, {"id": "b", "text": "Pericarditis position is sit up/lean forward; post-cardiac surgery preferred is semi-Fowler for comfort and lung expansion."}, {"id": "c", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "d", "text": "Pericarditis is best managed flat supine in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Pericarditis position is sit up/lean forward; post-cardiac surgery preferred is semi-Fowler for comfort and lung expansion. Condition-specific positioning can reduce pain and improve ventilation.', 'Pacemakers and ICDs - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Lifestyle diet teaching" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Lifestyle diet teaching" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Long-term dietary adherence reduces cardiovascular decompensation risk."}, {"id": "b", "text": "High-sodium canned foods are recommended in this note."}, {"id": "c", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "d", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}]'::jsonb, '["a"]'::jsonb, 'Correct because Diet teaching includes sodium restriction <2 g/day, low saturated fat/cholesterol, high fiber/fruits/vegetables, and avoiding processed high-salt foods. Long-term dietary adherence reduces cardiovascular decompensation risk.', 'Pacemakers and ICDs - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Pacemaker definition" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "Pacemaker definition" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Pacemakers are used to raise blood volume directly in this note."}, {"id": "b", "text": "Pacemakers only deliver defibrillation shocks in this note."}, {"id": "c", "text": "Device supports contraction when intrinsic rate is insufficient."}, {"id": "d", "text": "Goal is adequate heart rate/perfusion."}, {"id": "e", "text": "Pacemakers deliver electrical impulses."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: A pacemaker is an implanted device that delivers electrical impulses to maintain adequate heart rate and contraction.', 'Pacemakers and ICDs - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Temporary vs permanent pacing"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Temporary vs permanent pacing"? (Select all that apply)', '[{"id": "a", "text": "Temporary pacing can be used post-MI in this note."}, {"id": "b", "text": "Permanent pacemakers are external bedside-only in this note."}, {"id": "c", "text": "Temporary pacing is lifelong default therapy in this note."}, {"id": "d", "text": "Temporary and permanent pacing have different use contexts."}, {"id": "e", "text": "Permanent systems are implanted under skin."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Temporary pacing uses external wires (e.g., acute bradycardia/post-MI), while permanent pacing is surgically implanted under skin.', 'Pacemakers and ICDs - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Bradycardia indication" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Bradycardia indication" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Symptomatic bradycardia is listed indication."}, {"id": "b", "text": "Bradycardia is never paced in this note."}, {"id": "c", "text": "Symptoms drive urgency for intervention."}, {"id": "d", "text": "Asymptomatic tachycardia is primary pacing indication in this note."}, {"id": "e", "text": "<60 bpm threshold appears in note context."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Pacemaker indication includes symptomatic bradycardia with heart rate below 60 bpm.', 'Pacemakers and ICDs - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Heart block indication" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Heart block indication" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Second-degree type II block is listed indication."}, {"id": "b", "text": "First-degree block is the only mandatory pacing indication in this note."}, {"id": "c", "text": "Third-degree block is listed indication."}, {"id": "d", "text": "AV block is contraindication to pacing in this note."}, {"id": "e", "text": "Electrical signal interruption between atria and ventricles is emphasized."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Pacemaker indications include second-degree type II and third-degree AV block.', 'Pacemakers and ICDs - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Other pacing indications" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Other pacing indications" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Only ventricular tachycardia is paced in this note."}, {"id": "b", "text": "Asystole with reversible cause is listed indication."}, {"id": "c", "text": "Pacemaker use is excluded after cardiac surgery in this note."}, {"id": "d", "text": "Post-cardiac surgery prophylaxis is listed use."}, {"id": "e", "text": "Sick sinus syndrome is listed indication."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Other listed pacing indications include asystole with reversible cause, sick sinus syndrome, and post-cardiac surgery prophylaxis.', 'Pacemakers and ICDs - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "ECG post-implant monitoring" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "ECG post-implant monitoring" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Pacing spikes should be visible/appropriate."}, {"id": "b", "text": "ECG monitoring is immediate post-implant priority."}, {"id": "c", "text": "Rhythm verification is central to pacemaker safety."}, {"id": "d", "text": "ECG is unnecessary after implant in this note."}, {"id": "e", "text": "Spikes indicate malfunction by default in this note."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Nursing care includes ECG monitoring to verify pacing spikes and appropriate response.', 'Pacemakers and ICDs - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Pacing threshold"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Pacing threshold"? (Select all that apply)', '[{"id": "a", "text": "Threshold assessment is listed nursing priority."}, {"id": "b", "text": "Threshold is the maximum tolerated blood pressure in this note."}, {"id": "c", "text": "Capture reliability depends on adequate output above threshold."}, {"id": "d", "text": "Threshold has no relation to pacing effectiveness in this note."}, {"id": "e", "text": "Threshold refers to minimum effective current."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Pacing threshold is the lowest current needed to pace the heart.', 'Pacemakers and ICDs - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Failure to pace" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Failure to pace" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Failure to pace is normal after implantation in this note."}, {"id": "b", "text": "Immediate troubleshooting is required when no spike appears."}, {"id": "c", "text": "No pacing spike can indicate failure to pace."}, {"id": "d", "text": "Failure to pace shows spike with no QRS in this note."}, {"id": "e", "text": "Expected pacing without spike is abnormal."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Failure to pace is identified by absence of pacing spike when one is expected.', 'Pacemakers and ICDs - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Failure to capture" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Failure to capture" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Failure to capture means no spike present in this note."}, {"id": "b", "text": "Capture failure threatens perfusion."}, {"id": "c", "text": "Spike followed by QRS always indicates failure in this note."}, {"id": "d", "text": "Electrical output without depolarization is abnormal."}, {"id": "e", "text": "Spike without QRS defines failure to capture."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Failure to capture is pacing spike without resulting QRS complex.', 'Pacemakers and ICDs - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Arm movement restriction" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Arm movement restriction" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Arm restriction duration is 24–48 hours."}, {"id": "b", "text": "Arm restriction is unnecessary after implant in this note."}, {"id": "c", "text": "Post-op mobility guidance is part of nursing care."}, {"id": "d", "text": "Reason is prevention of lead displacement."}, {"id": "e", "text": "Aggressive overhead arm exercise is encouraged immediately in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: After implant, restrict affected arm movement for 24–48 hours to prevent lead displacement.', 'Pacemakers and ICDs - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Electromagnetic precautions" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "Electromagnetic precautions" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "MRI is listed as concern in note context."}, {"id": "b", "text": "Strong electromagnetic fields should be avoided."}, {"id": "c", "text": "Arc welding is recommended with pacemakers in this note."}, {"id": "d", "text": "Device safety teaching includes environmental risks."}, {"id": "e", "text": "All magnetic exposures are harmless in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Patients should avoid strong electromagnetic fields (e.g., MRI, arc welding, certain equipment).', 'Pacemakers and ICDs - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Patient ID and symptom reporting"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Patient ID and symptom reporting"? (Select all that apply)', '[{"id": "a", "text": "Device identification is unnecessary in emergencies in this note."}, {"id": "b", "text": "Pacemaker ID card is recommended."}, {"id": "c", "text": "Dizziness/syncope should be reported."}, {"id": "d", "text": "Hiccups are always benign in this context in this note."}, {"id": "e", "text": "Hiccups can signal diaphragm stimulation/lead displacement."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Patients should carry pacemaker ID card and report hiccups, dizziness, or syncope.', 'Pacemakers and ICDs - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "ICD function" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "ICD function" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "ICD shocks V-fib/V-tach per note."}, {"id": "b", "text": "ICD is for sinus bradycardia only in this note."}, {"id": "c", "text": "ICD is indicated for sudden death risk patients."}, {"id": "d", "text": "ICD does not treat ventricular arrhythmias in this note."}, {"id": "e", "text": "ICD monitors rhythm continuously."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: ICD continuously monitors rhythm and delivers shock for ventricular fibrillation or ventricular tachycardia.', 'Pacemakers and ICDs - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "If ICD fires" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "If ICD fires" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Lie down after ICD discharge is recommended."}, {"id": "b", "text": "ICD firing never requires follow-up in this note."}, {"id": "c", "text": "Persistent symptoms require provider notification."}, {"id": "d", "text": "Documenting shock time is recommended."}, {"id": "e", "text": "Exercise immediately after shock is advised in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: If ICD fires, patient should lie down, note time, and notify provider if symptoms continue.', 'Pacemakers and ICDs - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Bystander sensation with ICD" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Bystander sensation with ICD" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Bystanders may feel mild shock."}, {"id": "b", "text": "Education reduces fear around ICD events."}, {"id": "c", "text": "Mild shock to bystander is noted as not dangerous."}, {"id": "d", "text": "No one near patient feels anything in this note."}, {"id": "e", "text": "ICD discharge is fatal to bystanders in this note."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: People touching the patient during ICD discharge may feel mild shock that is not dangerous.', 'Pacemakers and ICDs - NCLEX', true, 65, 1, true);
