  VALUES (v_test_id, v_topic_id, 'Which statements about "ICD storm emergency" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "ICD storm emergency" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Immediate reporting is required."}, {"id": "b", "text": "Repeated firing is emergency in this note."}, {"id": "c", "text": "Repeated shocks can be ignored if conscious in this note."}, {"id": "d", "text": "Storm implies unstable arrhythmia burden."}, {"id": "e", "text": "ICD storm is routine expected function in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Repeated ICD firing should be reported immediately as an emergency (ICD storm).', 'Pacemakers and ICDs - NCLEX', true, 66, 1, true);
