  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Chest pain initial priorities"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Chest pain initial priorities"? (Select all that apply)', '[{"id": "a", "text": "12-lead ECG can be delayed several hours in this note."}, {"id": "b", "text": "ECG target is within 10 minutes."}, {"id": "c", "text": "Medications are given before ABC assessment in this note."}, {"id": "d", "text": "Oxygen threshold is O2 sat <90% in note."}, {"id": "e", "text": "ABCs come first in chest pain approach."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Chest pain protocol starts with ABC assessment, oxygen if saturation <90%, vitals, and 12-lead ECG within 10 minutes.', 'Pacemakers and ICDs - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Chest pain workflow continuation" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Chest pain workflow continuation" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Aspirin then nitroglycerin then morphine/heparin sequence is listed."}, {"id": "b", "text": "No labs are needed for chest pain in this note."}, {"id": "c", "text": "Large-bore IV is listed."}, {"id": "d", "text": "Troponin/CK-MB/BMP are listed labs."}, {"id": "e", "text": "Heparin is given before aspirin in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Protocol includes large-bore IV access, labs (troponin, CK-MB, BMP), and meds sequence: aspirin, nitroglycerin, morphine if needed, then heparin.', 'Pacemakers and ICDs - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Nitroglycerin safety" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Nitroglycerin safety" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "NTG is safe regardless of BP in this note."}, {"id": "b", "text": "Recent sildenafil is contraindication in this note."}, {"id": "c", "text": "BP check before NTG is emphasized."}, {"id": "d", "text": "SBP <90 is NTG hold criterion."}, {"id": "e", "text": "Sildenafil timing has no relevance in this note."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Check blood pressure before nitroglycerin; avoid nitroglycerin if systolic BP <90 or recent sildenafil use within 24–48 hours.', 'Pacemakers and ICDs - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Positioning HF/SOB" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Positioning HF/SOB" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Fowler position 30–45° is listed for HF/SOB."}, {"id": "b", "text": "Flat Trendelenburg is best for HF/SOB in this note."}, {"id": "c", "text": "Positioning reduces preload in this note."}, {"id": "d", "text": "Breathing relief is rationale for elevated HOB."}, {"id": "e", "text": "Position has no respiratory impact in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: For heart failure/SOB, best position is HOB elevated 30–45° (Fowler) to reduce preload and ease breathing.', 'Pacemakers and ICDs - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Positioning hypotension/shock" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "Positioning hypotension/shock" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Rationale is increased venous return."}, {"id": "b", "text": "Sit upright is best for hypotensive shock in this note."}, {"id": "c", "text": "Supine with legs elevated is listed for hypotension/shock."}, {"id": "d", "text": "Positioning is an early supportive intervention."}, {"id": "e", "text": "Leg lowering improves hypotension in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: For hypotension/shock, position supine with legs elevated 15–30° to increase venous return.', 'Pacemakers and ICDs - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Cardiogenic shock position caution"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Cardiogenic shock position caution"? (Select all that apply)', '[{"id": "a", "text": "Trendelenburg is avoided in cardiogenic shock."}, {"id": "b", "text": "Supine positioning is listed with caution."}, {"id": "c", "text": "Positioning differs from routine assumptions."}, {"id": "d", "text": "Cardiogenic shock requires sitting upright always in this note."}, {"id": "e", "text": "Trendelenburg is first-line for cardiogenic shock in this note."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: For cardiogenic shock, note recommends supine with caution and to avoid Trendelenburg.', 'Pacemakers and ICDs - NCLEX', true, 72, 1, true);
