  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Pericarditis and post-op positioning" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Pericarditis and post-op positioning" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Post-cardiac surgery semi-Fowler is listed."}, {"id": "b", "text": "Post-op position should always be Trendelenburg in this note."}, {"id": "c", "text": "Lung expansion is rationale for semi-Fowler post-op."}, {"id": "d", "text": "Pericarditis is best managed flat supine in this note."}, {"id": "e", "text": "Pericarditis relieved by sit up and leaning forward."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis position is sit up/lean forward; post-cardiac surgery preferred is semi-Fowler for comfort and lung expansion.', 'Pacemakers and ICDs - NCLEX', true, 73, 1, true);
