  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Lifestyle diet teaching" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Lifestyle diet teaching" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "High-sodium canned foods are recommended in this note."}, {"id": "b", "text": "Fiber should be minimized in this note."}, {"id": "c", "text": "Sodium target <2 g/day is listed."}, {"id": "d", "text": "Processed foods/deli meats/canned soups are discouraged."}, {"id": "e", "text": "High-fiber fruits/vegetables are recommended."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Diet teaching includes sodium restriction <2 g/day, low saturated fat/cholesterol, high fiber/fruits/vegetables, and avoiding processed high-salt foods.', 'Pacemakers and ICDs - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Lifestyle fluid/weight teaching" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Lifestyle fluid/weight teaching" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Fluid restriction 1.5–2 L/day is listed for HF."}, {"id": "b", "text": "Daily weight changes are irrelevant in this note."}, {"id": "c", "text": "Daily weight gain >2 lb should be reported."}, {"id": "d", "text": "Smoking cessation and weight-loss goals are included."}, {"id": "e", "text": "Unlimited fluids are advised for HF in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Lifestyle instructions include no smoking, weight loss if BMI >25, fluid restriction 1.5–2 L/day in HF, and daily weight reporting if gain >2 lb.', 'Pacemakers and ICDs - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "NCLEX perfusion tip" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "NCLEX perfusion tip" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Oxygenation is prioritized first."}, {"id": "b", "text": "Avoid Trendelenburg in hypotension is explicit tip."}, {"id": "c", "text": "Circulation support is prioritized first."}, {"id": "d", "text": "Trendelenburg is preferred for all hypotension in this note."}, {"id": "e", "text": "Documentation precedes circulation in this note."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: NCLEX tip emphasizes avoiding Trendelenburg for hypotension and prioritizing oxygenation/circulation first.', 'Pacemakers and ICDs - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Pacemaker definition"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Pacemaker definition"? (Select all that apply)', '[{"id": "a", "text": "Pacemakers deliver electrical impulses."}, {"id": "b", "text": "Device supports contraction when intrinsic rate is insufficient."}, {"id": "c", "text": "Pacemakers are used to raise blood volume directly in this note."}, {"id": "d", "text": "Goal is adequate heart rate/perfusion."}, {"id": "e", "text": "Pacemakers only deliver defibrillation shocks in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: A pacemaker is an implanted device that delivers electrical impulses to maintain adequate heart rate and contraction.', 'Pacemakers and ICDs - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Temporary vs permanent pacing" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Temporary vs permanent pacing" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Temporary pacing is lifelong default therapy in this note."}, {"id": "b", "text": "Permanent pacemakers are external bedside-only in this note."}, {"id": "c", "text": "Temporary pacing can be used post-MI in this note."}, {"id": "d", "text": "Permanent systems are implanted under skin."}, {"id": "e", "text": "Temporary and permanent pacing have different use contexts."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Temporary pacing uses external wires (e.g., acute bradycardia/post-MI), while permanent pacing is surgically implanted under skin.', 'Pacemakers and ICDs - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
